const s = $('Settings').first().json;
const REQUIRED = ['driveFolderId', 'spreadsheetId'];
// Stop early with a clear message if Settings still holds the template placeholders.
const unset = REQUIRED.filter(k => !String(s[k] ?? '').trim() || String(s[k]).includes('REPLACE_ME'));
if (unset.length) {
  throw new Error('Open the Settings node and fill in: ' + unset.join(', ') + '. They still contain REPLACE_ME placeholders.');
}

const allowed = String(s.allowedExtensions || '').toLowerCase().split(/[\s,]+/).filter(Boolean);
const minImageBytes = (Number(s.minImageSizeKB) || 0) * 1000;
const imageExt = ['png', 'jpg', 'jpeg', 'gif', 'bmp', 'webp', 'heic'];

// n8n reports sizes like "45.2 kB" or "1.3 MB". Returns null when unknown.
function sizeInBytes(bin) {
  const m = String(bin.fileSize || '').match(/([\d.]+)\s*([kmg]?)i?b/i);
  if (m) return parseFloat(m[1]) * { '': 1, k: 1e3, m: 1e6, g: 1e9 }[m[2].toLowerCase()];
  if (!bin.id && typeof bin.data === 'string' && bin.data.length > 100) return bin.data.length * 0.75;
  return null;
}
const slug = t => String(t || '').normalize('NFKD').replace(/[^\w.-]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 60);
function guessType(text) {
  const t = text.toLowerCase();
  if (/invoice|factura|rechnung|fattura|facture|\bbill\b/.test(t)) return 'Invoice';
  if (/receipt|recibo|quittung|ricevuta|reçu|payment confirmation/.test(t)) return 'Receipt';
  if (/statement|estado de cuenta|kontoauszug/.test(t)) return 'Statement';
  if (/quote|quotation|estimate|proposal|cotizaci|angebot|devis/.test(t)) return 'Quote';
  if (/contract|agreement|\bnda\b|contrato|vertrag/.test(t)) return 'Contract';
  return 'Other';
}

// Read the files straight from the trigger, so nothing depends on Settings passing binary data along.
const out = [];
$('New Email with Attachment').all().forEach((email, index) => {
  const m = email.json;
  const sender = (m.from && m.from.value && m.from.value[0]) || {};
  const fromAddr = String(sender.address || '').toLowerCase();
  const fromName = sender.name || fromAddr.split('@')[0];
  const received = m.date ? DateTime.fromJSDate(new Date(m.date)) : $now;
  const subject = m.subject || '';

  for (const [key, bin] of Object.entries(email.binary || {})) {
    const original = bin.fileName || key;
    const ext = String(bin.fileExtension || (original.includes('.') ? original.split('.').pop() : '')).toLowerCase();
    if (allowed.length && !allowed.includes(ext)) continue;
    const bytes = sizeInBytes(bin);
    // Small images are almost always signature logos and inline icons.
    if (imageExt.includes(ext) && bytes !== null && bytes < minImageBytes) continue;

    out.push({
      json: {
        messageId: m.id,
        threadId: m.threadId,
        received: received.toFormat('yyyy-MM-dd HH:mm'),
        fromName,
        fromAddr,
        subject,
        originalName: original,
        fileName: `${received.toFormat('yyyy-MM-dd')}_${slug(fromName) || 'sender'}_${slug(original) || key + '.' + ext}`,
        docType: guessType(original + ' ' + subject),
        sizeKB: bytes === null ? '' : Math.round(bytes / 1000),
        emailLink: `https://mail.google.com/mail/u/${s.myAddress || 0}/#all/${m.threadId}`,
        driveFolderId: s.driveFolderId,
        spreadsheetId: s.spreadsheetId,
        sheetName: s.sheetName,
        savedLabelId: s.savedLabelId,
      },
      binary: { data: bin },
      pairedItem: { item: index },
    });
  }
});
return out;
